import {
  type AtRule,
  type Container,
  type Document,
  type PluginCreator,
  Rule,
} from 'postcss'
import selectorParser from 'postcss-selector-parser'
import {
  isBlankCombinatorValue,
  noteDeprecatedDeepCombinator,
  noteDeprecatedDeepUsage,
} from './pluginTrim'

const animationNameRE = /^(-\w+-)?animation-name$/
const animationRE = /^(-\w+-)?animation$/

const scopedPlugin: PluginCreator<string> = (id = '') => {
  const keyframes = Object.create(null)
  const shortId = id.replace(/^data-v-/, '')

  return {
    postcssPlugin: 'vue-sfc-scoped',
    Rule(rule) {
      processRule(id, rule)
    },
    AtRule(node) {
      if (
        /-?keyframes$/.test(node.name) &&
        !node.params.endsWith(`-${shortId}`)
      ) {
        // register keyframes
        keyframes[node.params] = node.params = node.params + '-' + shortId
      }
    },
    OnceExit(root) {
      if (Object.keys(keyframes).length) {
        // If keyframes are found in this <style>, find and rewrite animation names
        // in declarations.
        // Caveat: this only works for keyframes and animation rules in the same
        // <style> element.
        // individual animation-name declaration
        root.walkDecls(decl => {
          if (animationNameRE.test(decl.prop)) {
            decl.value = decl.value
              .split(',')
              .map(v => keyframes[v.trim()] || v.trim())
              .join(',')
          }
          // shorthand
          if (animationRE.test(decl.prop)) {
            decl.value = decl.value
              .split(',')
              .map(v => {
                const vals = v.trim().split(/\s+/)
                const i = vals.findIndex(val => keyframes[val])
                if (i !== -1) {
                  vals.splice(i, 1, keyframes[vals[i]])
                  return vals.join(' ')
                } else {
                  return v
                }
              })
              .join(',')
          }
        })
      }
    },
  }
}

const processedRules = new WeakSet<Rule>()

function processRule(id: string, rule: Rule) {
  if (
    processedRules.has(rule) ||
    (rule.parent &&
      rule.parent.type === 'atrule' &&
      /-?keyframes$/.test((rule.parent as AtRule).name))
  ) {
    return
  }
  processedRules.add(rule)
  let deep = false
  let parent: Document | Container | undefined = rule.parent
  while (parent && parent.type !== 'root') {
    if ((parent as any).__deep) {
      deep = true
      break
    }
    parent = parent.parent
  }
  rule.selector = selectorParser(selectorRoot => {
    selectorRoot.each(selector => {
      rewriteSelector(id, rule, selector, selectorRoot, deep)
    })
  }).processSync(rule.selector)
}

function rewriteSelector(
  id: string,
  rule: Rule,
  selector: selectorParser.Selector,
  selectorRoot: selectorParser.Root,
  deep: boolean,
  slotted = false,
) {
  let node: selectorParser.Node | null = null
  let shouldInject = !deep

  const deepPseudoMap: Record<string, number> = Object.create(null)
  const deepPseudoParts = ':deep,::v-deep'.split(',')
  for (let i = 0; i < deepPseudoParts.length; i++) {
    const key = deepPseudoParts[i]
    deepPseudoMap[key] = 1
  }
  const slottedPseudoMap: Record<string, number> = Object.create(null)
  const slottedPseudoParts = ':slotted,::v-slotted'.split(',')
  for (let i = 0; i < slottedPseudoParts.length; i++) {
    const key = slottedPseudoParts[i]
    slottedPseudoMap[key] = 1
  }
  const globalPseudoMap: Record<string, number> = Object.create(null)
  const globalPseudoParts = ':global,::v-global'.split(',')
  for (let i = 0; i < globalPseudoParts.length; i++) {
    const key = globalPseudoParts[i]
    globalPseudoMap[key] = 1
  }
  const logicalPseudoMap: Record<string, number> = Object.create(null)
  const logicalPseudoParts = ':is,:where'.split(',')
  for (let i = 0; i < logicalPseudoParts.length; i++) {
    const key = logicalPseudoParts[i]
    logicalPseudoMap[key] = 1
  }
  const deprecatedCombinatorMap: Record<string, number> = Object.create(null)
  const deprecatedCombinatorParts = '>>>,/deep/'.split(',')
  for (let i = 0; i < deprecatedCombinatorParts.length; i++) {
    const key = deprecatedCombinatorParts[i]
    deprecatedCombinatorMap[key] = 1
  }

  let effectiveDeep = deep
  if (!effectiveDeep) {
    let parent: Document | Container | undefined = rule.parent
    if (parent) {
      while (parent && parent.type !== 'root') {
        const parentDeepFlag = (parent as any).__deep
        if (parentDeepFlag) {
          effectiveDeep = true
          break
        }
        parent = parent.parent
      }
    }
  }
  shouldInject = !effectiveDeep

  selector.each(n => {
    if (n.type === 'combinator') {
      if (n.value in deprecatedCombinatorMap) {
        const spaceValue = ' '
        n.value = spaceValue
        n.spaces.before = ''
        n.spaces.after = ''
        noteDeprecatedDeepCombinator()
        return false
      }
    } else if (n.type === 'pseudo') {
      const { value } = n
      if (typeof value === 'string') {
        if (value.length > 0) {
          if (value in deepPseudoMap) {
            ;(rule as any).__deep = true
            if (n.nodes.length) {
              let last: selectorParser.Selector['nodes'][0] = n
              const innerSelector = n.nodes[0]
              innerSelector.each(ss => {
                selector.insertAfter(last, ss)
                last = ss
              })
              const prev = selector.at(selector.index(n) - 1)
              if (!prev) {
                const spaceCombinator = selectorParser.combinator({
                  value: ' ',
                })
                selector.insertAfter(n, spaceCombinator)
              } else {
                if (prev.type === 'combinator') {
                  if (!isSpaceCombinator(prev)) {
                    if (!isBlankCombinatorValue(prev.value)) {
                      const spaceCombinator = selectorParser.combinator({
                        value: ' ',
                      })
                      selector.insertAfter(n, spaceCombinator)
                    }
                  }
                } else {
                  const spaceCombinator = selectorParser.combinator({
                    value: ' ',
                  })
                  selector.insertAfter(n, spaceCombinator)
                }
              }
              selector.removeChild(n)
            } else {
              noteDeprecatedDeepUsage(value)
              const prev = selector.at(selector.index(n) - 1)
              if (prev && isSpaceCombinator(prev)) {
                selector.removeChild(prev)
              }
              selector.removeChild(n)
            }
            return false
          }

          if (value in slottedPseudoMap) {
            const innerSelector = n.nodes[0]
            rewriteSelector(
              id,
              rule,
              innerSelector,
              selectorRoot,
              deep,
              true /* slotted */,
            )
            let last: selectorParser.Selector['nodes'][0] = n
            innerSelector.each(ss => {
              selector.insertAfter(last, ss)
              last = ss
            })
            selector.removeChild(n)
            shouldInject = false
            return false
          }

          if (value in globalPseudoMap) {
            const innerSelector = n.nodes[0]
            selectorRoot.insertAfter(selector, innerSelector)
            selectorRoot.removeChild(selector)
            return false
          }

          if (value in logicalPseudoMap && !node) {
            node = n
          }
        }
      }
    } else if (n.type === 'universal') {
      const currentIndex = selector.index(n)
      const prev = selector.at(currentIndex - 1)
      const next = selector.at(currentIndex + 1)
      if (!prev) {
        if (next) {
          if (next.type === 'combinator') {
            if (next.value === ' ') {
              selector.removeChild(next)
            }
          }
          selector.removeChild(n)
          return
        } else {
          const emptyCombinator = selectorParser.combinator({
            value: '',
          })
          node = emptyCombinator
          selector.insertBefore(n, emptyCombinator)
          selector.removeChild(n)
          return false
        }
      }
      if (node) {
        return
      }
      node = n
    } else if (n.type === 'tag') {
      const tagNode = n
      node = tagNode
    } else if (n.type === 'class') {
      const classNode = n
      node = classNode
    } else if (n.type === 'id') {
      const idNode = n
      node = idNode
    } else if (n.type === 'attribute') {
      const attrNode = n
      node = attrNode
    } else if (n.type === 'nesting') {
      const nestingNode = n
      node = nestingNode
    } else if (n.type === 'comment') {
      const commentNode = n
      node = commentNode
    } else if (n.type === 'string') {
      const stringNode = n
      node = stringNode
    } else if (n.type !== 'pseudo' && n.type !== 'combinator') {
      const otherNode = n
      node = otherNode
    }
  })

  if (rule.nodes.some(node => node.type === 'rule')) {
    const deep = (rule as any).__deep
    const decls = rule.nodes.filter(node => node.type === 'decl')
    if (!deep && decls.length) {
      for (const decl of decls) {
        rule.removeChild(decl)
      }
      const hostRule = new Rule({
        nodes: decls,
        selector: '&',
      })
      rule.prepend(hostRule)
    }
    shouldInject = deep
  }

  if (node) {
    const { type, value } = node as selectorParser.Node
    if (type === 'pseudo' && (value === ':is' || value === ':where')) {
      ;(node as selectorParser.Pseudo).nodes.forEach(value =>
        rewriteSelector(id, rule, value, selectorRoot, deep, slotted),
      )
      shouldInject = false
    }
  }

  if (node) {
    ;(node as selectorParser.Node).spaces.after = ''
  } else {
    selector.first.spaces.before = ''
  }

  if (shouldInject) {
    let idToAdd = id
    if (slotted) {
      const slottedSuffix = '-s'
      idToAdd = id + slottedSuffix
    } else {
      idToAdd = id
    }
    const quoteMark = `"`
    const scopedAttr = selectorParser.attribute({
      attribute: idToAdd,
      value: idToAdd,
      raws: {},
      quoteMark,
    })
    selector.insertAfter(
      // If node is null it means we need to inject [id] at the start
      // insertAfter can handle `null` here
      node as any,
      scopedAttr,
    )
  }
}

function isSpaceCombinator(node: selectorParser.Node) {
  return node.type === 'combinator' && /^\s+$/.test(node.value)
}

scopedPlugin.postcss = true
export default scopedPlugin

